# Count the total number of policies used by customer "Dayana Robel"
dayana_policy_count = customer.WHERE(
    customer_name == "Dayana Robel"
).CALCULATE(
    total_policies = COUNT(customers_policy)
)

# Find the maximum active_to_date across all contact channels for Tillman Ernser
latest_active_to_date = Customers.WHERE(
    customer_name == "Tillman Ernser"
).CALCULATE(
    latest_active_to_date=MAX(customer_contact_channel.active_to_date)
)

# Get names, classes, and ranks of all captains
captain_info = captains.CALCULATE(
    name=name,
    class=class,
    rank=rank
)

# Find distinct last names of students who received president votes, excluding those with advisor 2192
students_with_president_votes = voting_records.WHERE(
    president_vote != None
).CALCULATE(
    received_vote_stuid = president_vote
).PARTITION(
    name="vote_recipients", 
    by=received_vote_stuid
).CALCULATE(
    stuid = received_vote_stuid
)

# Get the last names of these students, excluding those with advisor 2192
distinct_lastnames = students.WHERE(
    (HAS(students_with_president_votes.WHERE(stuid == stuid)) == 1) &
    (advisor != 2192)
).PARTITION(
    name="lastname_groups", 
    by=lname
).CALCULATE(
    last_name = lname
)

columbus_crew_players = player.WHERE(
    team_join.name == "Columbus Crew"
).CALCULATE(
    player_name=player,
    years_played=years_played
)

# Filter customer orders before the specified datetime and sum order quantities
total_products_ordered = customers_and_addresses.CALCULATE(
    total_amount=SUM(
        customer_order.WHERE(
            order_date < "2018-03-17 07:13:53"
        ).order_item.order_quantity
    )
)

# Filter volumes by artists who are at most 25 years old and calculate average weeks on top
young_artist_volumes_avg = volumes.WHERE(
    artist.age <= 25
).CALCULATE(
    avg_weeks_on_top=AVG(weeks_on_top)
)
